#include "gpu.h"
#include <stddef.h>
#include <stdint.h>
#include <tonic/tonic.h>
/* SPIR-V from shaders/, generated by the Makefile (glslangValidator --vn). */
#include "level_vert.h"
#include "level_frag.h"
#include "level_flat_frag.h"
#include "ui_vert.h"
#include "ui_frag.h"
#include "overlay_vert.h"
#include "overlay_frag.h"

static SDL_GPUShader *shader(gpu *g, const uint32_t *code, size_t size, SDL_GPUShaderStage stage, Uint32 samplers,
                             Uint32 uniform_buffers) {
    SDL_GPUShaderCreateInfo info;
    SDL_zero(info);
    info.code = (const Uint8 *)code;
    info.code_size = size;
    info.entrypoint = "main";
    info.format = SDL_GPU_SHADERFORMAT_SPIRV;
    info.stage = stage;
    info.num_samplers = samplers;
    info.num_uniform_buffers = uniform_buffers;
    SDL_GPUShader *s = SDL_CreateGPUShader(g->device, &info);
    if (!s) SDL_Log("shader: %s", SDL_GetError());
    return s;
}

static SDL_GPUColorTargetBlendState alpha_blend(void) {
    SDL_GPUColorTargetBlendState b;
    SDL_zero(b);
    b.enable_blend = true;
    b.src_color_blendfactor = SDL_GPU_BLENDFACTOR_SRC_ALPHA;
    b.dst_color_blendfactor = SDL_GPU_BLENDFACTOR_ONE_MINUS_SRC_ALPHA;
    b.color_blend_op = SDL_GPU_BLENDOP_ADD;
    b.src_alpha_blendfactor = SDL_GPU_BLENDFACTOR_ONE;
    b.dst_alpha_blendfactor = SDL_GPU_BLENDFACTOR_ONE_MINUS_SRC_ALPHA;
    b.alpha_blend_op = SDL_GPU_BLENDOP_ADD;
    return b;
}

static SDL_GPUSampleCount sample_count(int samples) {
    switch (samples) {
    case 2: return SDL_GPU_SAMPLECOUNT_2;
    case 4: return SDL_GPU_SAMPLECOUNT_4;
    case 8: return SDL_GPU_SAMPLECOUNT_8;
    default: return SDL_GPU_SAMPLECOUNT_1;
    }
}

static bool msaa_supported(const gpu *g, int samples) {
    if (samples == 1) return true;
    if (samples != 2 && samples != 4 && samples != 8) return false;
    return SDL_GPUTextureSupportsSampleCount(g->device, g->swapchain_format, sample_count(samples)) &&
           SDL_GPUTextureSupportsSampleCount(g->device, g->depth_format, sample_count(samples));
}

/* tc_vertex is the packed GPU layout: pos3, normal3, uv2 floats, 3 x rgba8 baked sets, uv2 (52 bytes).
 * coverage: alpha to coverage (only takes effect with multisampling). */
static SDL_GPUGraphicsPipeline *level_pipeline(gpu *g, SDL_GPUShader *vs, SDL_GPUShader *fs, bool blended,
                                               bool depth_write, bool coverage) {
    static const SDL_GPUVertexAttribute attributes[] = {
        {0, 0, SDL_GPU_VERTEXELEMENTFORMAT_FLOAT3, offsetof(tc_vertex, position)},
        {1, 0, SDL_GPU_VERTEXELEMENTFORMAT_FLOAT3, offsetof(tc_vertex, normal)},
        {2, 0, SDL_GPU_VERTEXELEMENTFORMAT_FLOAT2, offsetof(tc_vertex, uv)},
        {3, 0, SDL_GPU_VERTEXELEMENTFORMAT_UBYTE4_NORM, offsetof(tc_vertex, color)},
        {4, 0, SDL_GPU_VERTEXELEMENTFORMAT_UBYTE4_NORM, offsetof(tc_vertex, color) + 4},
        {5, 0, SDL_GPU_VERTEXELEMENTFORMAT_UBYTE4_NORM, offsetof(tc_vertex, color) + 8},
        {6, 0, SDL_GPU_VERTEXELEMENTFORMAT_FLOAT2, offsetof(tc_vertex, uv2)},
    };
    SDL_GPUVertexBufferDescription buffer;
    SDL_zero(buffer);
    buffer.slot = 0;
    buffer.pitch = sizeof(tc_vertex);
    buffer.input_rate = SDL_GPU_VERTEXINPUTRATE_VERTEX;

    SDL_GPUColorTargetDescription color;
    SDL_zero(color);
    color.format = g->swapchain_format;
    if (blended) color.blend_state = alpha_blend();

    SDL_GPUGraphicsPipelineCreateInfo info;
    SDL_zero(info);
    info.vertex_shader = vs;
    info.fragment_shader = fs;
    info.vertex_input_state.vertex_buffer_descriptions = &buffer;
    info.vertex_input_state.num_vertex_buffers = 1;
    info.vertex_input_state.vertex_attributes = attributes;
    info.vertex_input_state.num_vertex_attributes = SDL_arraysize(attributes);
    info.primitive_type = SDL_GPU_PRIMITIVETYPE_TRIANGLELIST;
    info.rasterizer_state.fill_mode = SDL_GPU_FILLMODE_FILL;
    info.rasterizer_state.cull_mode = SDL_GPU_CULLMODE_NONE;  /* winding of OpenSpace elements not yet confirmed */
    info.rasterizer_state.front_face = SDL_GPU_FRONTFACE_COUNTER_CLOCKWISE;
    info.rasterizer_state.enable_depth_clip = true;
    info.multisample_state.sample_count = sample_count(g->msaa);
    info.multisample_state.enable_alpha_to_coverage = coverage && g->msaa > 1;
    info.depth_stencil_state.enable_depth_test = true;
    info.depth_stencil_state.enable_depth_write = depth_write;
    info.depth_stencil_state.compare_op = SDL_GPU_COMPAREOP_LESS;
    info.target_info.color_target_descriptions = &color;
    info.target_info.num_color_targets = 1;
    info.target_info.depth_stencil_format = g->depth_format;
    info.target_info.has_depth_stencil_target = true;
    SDL_GPUGraphicsPipeline *p = SDL_CreateGPUGraphicsPipeline(g->device, &info);
    if (!p) SDL_Log("pipeline: %s", SDL_GetError());
    return p;
}

static SDL_GPUGraphicsPipeline *ui_pipeline(gpu *g, SDL_GPUShader *vs, SDL_GPUShader *fs) {
    SDL_GPUColorTargetDescription color;
    SDL_zero(color);
    color.format = g->swapchain_format;
    color.blend_state = alpha_blend();
    SDL_GPUGraphicsPipelineCreateInfo info;
    SDL_zero(info);
    info.vertex_shader = vs;
    info.fragment_shader = fs;
    info.primitive_type = SDL_GPU_PRIMITIVETYPE_TRIANGLELIST;
    info.rasterizer_state.fill_mode = SDL_GPU_FILLMODE_FILL;
    info.rasterizer_state.cull_mode = SDL_GPU_CULLMODE_NONE;
    info.rasterizer_state.enable_depth_clip = true;
    info.multisample_state.sample_count = SDL_GPU_SAMPLECOUNT_1;
    info.target_info.color_target_descriptions = &color;
    info.target_info.num_color_targets = 1;
    SDL_GPUGraphicsPipeline *p = SDL_CreateGPUGraphicsPipeline(g->device, &info);
    if (!p) SDL_Log("ui pipeline: %s", SDL_GetError());
    return p;
}

static SDL_GPUSampler *sampler(gpu *g, SDL_GPUSamplerAddressMode address, bool anisotropy, bool nearest) {
    SDL_GPUSamplerCreateInfo info;
    SDL_zero(info);
    info.min_filter = nearest ? SDL_GPU_FILTER_NEAREST : SDL_GPU_FILTER_LINEAR;
    info.mag_filter = nearest ? SDL_GPU_FILTER_NEAREST : SDL_GPU_FILTER_LINEAR;
    info.mipmap_mode = nearest ? SDL_GPU_SAMPLERMIPMAPMODE_NEAREST : SDL_GPU_SAMPLERMIPMAPMODE_LINEAR;
    info.address_mode_u = info.address_mode_v = info.address_mode_w = address;
    info.min_lod = 0;
    info.max_lod = 1000;
    info.enable_anisotropy = anisotropy;
    info.max_anisotropy = anisotropy ? 16 : 1;
    return SDL_CreateGPUSampler(g->device, &info);
}

static void release_level_pipelines(gpu *g) {
    SDL_GPUGraphicsPipeline **pipelines[] = {&g->textured, &g->flat, &g->textured_blended, &g->flat_no_depth_write};
    for (size_t i = 0; i < SDL_arraysize(pipelines); i++) {
        if (*pipelines[i]) SDL_ReleaseGPUGraphicsPipeline(g->device, *pipelines[i]);
        *pipelines[i] = NULL;
    }
}

/* The four level pipelines for g->msaa. Only the opaque textured one uses alpha to coverage: blended surfaces need
 * their alpha for blending, flat ones have none. */
static bool level_pipelines(gpu *g) {
    g->textured = level_pipeline(g, g->level_vs, g->textured_fs, false, true, true);
    g->flat = level_pipeline(g, g->level_vs, g->flat_fs, false, true, false);
    g->textured_blended = level_pipeline(g, g->level_vs, g->textured_fs, true, false, false);
    g->flat_no_depth_write = level_pipeline(g, g->level_vs, g->flat_fs, false, false, false);
    if (g->textured && g->flat && g->textured_blended && g->flat_no_depth_write) return true;
    release_level_pipelines(g);
    return false;
}

bool gpu_set_msaa(gpu *g, int samples) {
    if (!msaa_supported(g, samples)) return false;
    if (samples == g->msaa && g->textured) return true;
    SDL_WaitForGPUIdle(g->device);
    release_level_pipelines(g);
    int previous = g->msaa;
    g->msaa = samples;
    if (level_pipelines(g)) return true;
    g->msaa = previous;  /* keep drawing with what worked */
    level_pipelines(g);
    return false;
}

int gpu_next_msaa(const gpu *g) {
    for (int s = g->msaa * 2; s <= 8; s *= 2)
        if (msaa_supported(g, s)) return s;
    return 1;
}

bool gpu_init(gpu *g, SDL_Window *window, int msaa) {
    SDL_zerop(g);
    g->window = window;
    /* TONIC_GPU_DEBUG=1: the backend's validation layers (when installed). */
    g->device = SDL_CreateGPUDevice(SDL_GPU_SHADERFORMAT_SPIRV, SDL_getenv("TONIC_GPU_DEBUG") != NULL, NULL);
    if (!g->device) return false;
    if (!SDL_ClaimWindowForGPUDevice(g->device, window)) return false;
    SDL_PropertiesID props = SDL_GetGPUDeviceProperties(g->device);
    SDL_Log("GPU: %s, %s (%s)", SDL_GetGPUDeviceDriver(g->device),
            SDL_GetStringProperty(props, SDL_PROP_GPU_DEVICE_NAME_STRING, "unknown device"),
            SDL_GetStringProperty(props, SDL_PROP_GPU_DEVICE_DRIVER_INFO_STRING, "no driver info"));
    g->swapchain_format = SDL_GetGPUSwapchainTextureFormat(g->device, window);
    g->depth_format = SDL_GPUTextureSupportsFormat(g->device, SDL_GPU_TEXTUREFORMAT_D32_FLOAT, SDL_GPU_TEXTURETYPE_2D,
                                                   SDL_GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET)
                          ? SDL_GPU_TEXTUREFORMAT_D32_FLOAT : SDL_GPU_TEXTUREFORMAT_D24_UNORM;

    /* The largest supported sample count up to the wanted one. */
    g->msaa = 1;
    for (int s = 2; s <= msaa; s *= 2)
        if (msaa_supported(g, s)) g->msaa = s;
    SDL_Log("GPU: antialiasing %dx MSAA", g->msaa);

    g->level_vs = shader(g, level_vert, sizeof level_vert, SDL_GPU_SHADERSTAGE_VERTEX, 0, 2);
    g->textured_fs = shader(g, level_frag, sizeof level_frag, SDL_GPU_SHADERSTAGE_FRAGMENT, 2, 2);
    g->flat_fs = shader(g, level_flat_frag, sizeof level_flat_frag, SDL_GPU_SHADERSTAGE_FRAGMENT, 1, 1);
    SDL_GPUShader *ui_vs = shader(g, ui_vert, sizeof ui_vert, SDL_GPU_SHADERSTAGE_VERTEX, 0, 1);
    SDL_GPUShader *ui_fs = shader(g, ui_frag, sizeof ui_frag, SDL_GPU_SHADERSTAGE_FRAGMENT, 1, 0);
    SDL_GPUShader *overlay_vs = shader(g, overlay_vert, sizeof overlay_vert, SDL_GPU_SHADERSTAGE_VERTEX, 0, 1);
    SDL_GPUShader *overlay_fs = shader(g, overlay_frag, sizeof overlay_frag, SDL_GPU_SHADERSTAGE_FRAGMENT, 1, 1);
    bool ok = g->level_vs && g->textured_fs && g->flat_fs && ui_vs && ui_fs && overlay_vs && overlay_fs;
    if (ok && !level_pipelines(g) && g->msaa > 1) {
        SDL_Log("GPU: no pipelines with %dx MSAA, trying without", g->msaa);
        g->msaa = 1;
        level_pipelines(g);
    }
    if (ok) g->ui = ui_pipeline(g, ui_vs, ui_fs);
    if (ok) g->overlay = ui_pipeline(g, overlay_vs, overlay_fs);
    SDL_GPUShader *ui_shaders[] = {ui_vs, ui_fs, overlay_vs, overlay_fs};
    for (size_t i = 0; i < SDL_arraysize(ui_shaders); i++)
        if (ui_shaders[i]) SDL_ReleaseGPUShader(g->device, ui_shaders[i]);
    if (!g->textured || !g->ui || !g->overlay) {
        SDL_SetError("could not create the pipelines (see the log)");
        return false;
    }

    g->repeat_sampler = sampler(g, SDL_GPU_SAMPLERADDRESSMODE_REPEAT, true, false);
    g->clamp_sampler = sampler(g, SDL_GPU_SAMPLERADDRESSMODE_CLAMP_TO_EDGE, false, false);
    g->ui_sampler = sampler(g, SDL_GPU_SAMPLERADDRESSMODE_CLAMP_TO_EDGE, false, false);
    g->nearest_sampler = sampler(g, SDL_GPU_SAMPLERADDRESSMODE_CLAMP_TO_EDGE, false, true);
    if (!g->repeat_sampler || !g->clamp_sampler || !g->ui_sampler || !g->nearest_sampler) return false;

    gpu_upload u;
    if (!gpu_upload_begin(g, &u)) return false;
    SDL_Surface *white = SDL_CreateSurface(1, 1, SDL_PIXELFORMAT_RGBA32);
    if (white) {
        SDL_FillSurfaceRect(white, NULL, 0xFFFFFFFFu);
        g->white = gpu_upload_surface(g, &u, white, false);
        SDL_DestroySurface(white);
    }
    return gpu_upload_end(g, &u) && g->white;
}

void gpu_quit(gpu *g) {
    if (!g->device) return;
    SDL_WaitForGPUIdle(g->device);
    release_level_pipelines(g);
    if (g->ui) SDL_ReleaseGPUGraphicsPipeline(g->device, g->ui);
    if (g->overlay) SDL_ReleaseGPUGraphicsPipeline(g->device, g->overlay);
    SDL_GPUShader *shaders[] = {g->level_vs, g->textured_fs, g->flat_fs};
    for (size_t i = 0; i < SDL_arraysize(shaders); i++)
        if (shaders[i]) SDL_ReleaseGPUShader(g->device, shaders[i]);
    SDL_GPUSampler *samplers[] = {g->repeat_sampler, g->clamp_sampler, g->ui_sampler, g->nearest_sampler};
    for (size_t i = 0; i < SDL_arraysize(samplers); i++)
        if (samplers[i]) SDL_ReleaseGPUSampler(g->device, samplers[i]);
    if (g->white) SDL_ReleaseGPUTexture(g->device, g->white);
    if (g->depth) SDL_ReleaseGPUTexture(g->device, g->depth);
    if (g->msaa_color) SDL_ReleaseGPUTexture(g->device, g->msaa_color);
    if (g->window) SDL_ReleaseWindowFromGPUDevice(g->device, g->window);
    SDL_DestroyGPUDevice(g->device);
    SDL_zerop(g);
}

/* ---- uploads ---- */

bool gpu_upload_begin(gpu *g, gpu_upload *u) {
    SDL_zerop(u);
    u->cmd = SDL_AcquireGPUCommandBuffer(g->device);
    if (!u->cmd) return false;
    u->pass = SDL_BeginGPUCopyPass(u->cmd);
    return u->pass != NULL;
}

/* Copies `size` bytes into a fresh transfer buffer; released at once (SDL frees it when the GPU is done). */
static SDL_GPUTransferBuffer *stage(gpu *g, const void *data, Uint32 size) {
    SDL_GPUTransferBufferCreateInfo info;
    SDL_zero(info);
    info.usage = SDL_GPU_TRANSFERBUFFERUSAGE_UPLOAD;
    info.size = size;
    SDL_GPUTransferBuffer *tb = SDL_CreateGPUTransferBuffer(g->device, &info);
    if (!tb) return NULL;
    void *p = SDL_MapGPUTransferBuffer(g->device, tb, false);
    if (!p) { SDL_ReleaseGPUTransferBuffer(g->device, tb); return NULL; }
    SDL_memcpy(p, data, size);
    SDL_UnmapGPUTransferBuffer(g->device, tb);
    return tb;
}

/* Fully transparent texels take the average colour of their neighbours, growing inwards from the opaque ones a ring
 * per pass; whatever is still unreached after `passes` gets the image's average opaque colour. Alpha is untouched. */
static void bleed_alpha(SDL_Surface *s, int passes) {
    const int w = s->w, h = s->h, pitch = s->pitch;
    Uint8 *px = s->pixels;
    Uint8 *known = SDL_malloc((size_t)w * (size_t)h);
    if (!known) return;
    int unknown = 0;
    Uint64 sum[3] = {0, 0, 0}, opaque = 0;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            const Uint8 *p = px + y * pitch + x * 4;
            known[y * w + x] = p[3] != 0;
            if (p[3]) { sum[0] += p[0]; sum[1] += p[1]; sum[2] += p[2]; opaque++; }
            else unknown++;
        }
    if (unknown == 0 || opaque == 0) { SDL_free(known); return; }
    for (int pass = 0; pass < passes && unknown > 0; pass++) {
        int filled = 0;
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                if (known[y * w + x]) continue;
                int r = 0, gr = 0, b = 0, n = 0;
                for (int dy = -1; dy <= 1; dy++)
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx, ny = y + dy;
                        /* Only rings from earlier passes (1), not texels filled in this one (2). */
                        if (nx < 0 || ny < 0 || nx >= w || ny >= h || known[ny * w + nx] != 1) continue;
                        const Uint8 *q = px + ny * pitch + nx * 4;
                        r += q[0]; gr += q[1]; b += q[2]; n++;
                    }
                if (!n) continue;
                Uint8 *p = px + y * pitch + x * 4;
                p[0] = (Uint8)(r / n); p[1] = (Uint8)(gr / n); p[2] = (Uint8)(b / n);
                known[y * w + x] = 2;
                filled++;
            }
        for (int i = 0; i < w * h; i++) if (known[i] == 2) known[i] = 1;
        unknown -= filled;
        if (!filled) break;
    }
    if (unknown > 0)
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                if (known[y * w + x]) continue;
                Uint8 *p = px + y * pitch + x * 4;
                p[0] = (Uint8)(sum[0] / opaque); p[1] = (Uint8)(sum[1] / opaque); p[2] = (Uint8)(sum[2] / opaque);
            }
    SDL_free(known);
}

static bool has_transparent_texel(const SDL_Surface *s) {
    for (int y = 0; y < s->h; y++) {
        const Uint8 *row = (const Uint8 *)s->pixels + y * s->pitch;
        for (int x = 0; x < s->w; x++) if (row[x * 4 + 3] == 0) return true;
    }
    return false;
}

SDL_GPUTexture *gpu_upload_surface(gpu *g, gpu_upload *u, SDL_Surface *s, bool mipmaps) {
    SDL_Surface *rgba = s->format == SDL_PIXELFORMAT_RGBA32 ? s : SDL_ConvertSurface(s, SDL_PIXELFORMAT_RGBA32);
    if (!rgba) return NULL;
    if (mipmaps && has_transparent_texel(rgba)) {
        if (rgba == s) rgba = SDL_DuplicateSurface(s);  /* the caller's pixels stay as they were */
        if (!rgba) return NULL;
        bleed_alpha(rgba, 16);
    }
    SDL_GPUTexture *t = NULL;
    Uint32 levels = 1;
    if (mipmaps)
        for (int m = SDL_max(rgba->w, rgba->h); m > 1; m >>= 1) levels++;
    SDL_GPUTextureCreateInfo info;
    SDL_zero(info);
    info.type = SDL_GPU_TEXTURETYPE_2D;
    info.format = SDL_GPU_TEXTUREFORMAT_R8G8B8A8_UNORM;  /* not sRGB, as the Metal build */
    info.usage = SDL_GPU_TEXTUREUSAGE_SAMPLER | (levels > 1 ? SDL_GPU_TEXTUREUSAGE_COLOR_TARGET : 0);
    info.width = (Uint32)rgba->w;
    info.height = (Uint32)rgba->h;
    info.layer_count_or_depth = 1;
    info.num_levels = levels;
    info.sample_count = SDL_GPU_SAMPLECOUNT_1;
    SDL_GPUTransferBuffer *tb = stage(g, rgba->pixels, (Uint32)(rgba->pitch * rgba->h));
    if (tb) t = SDL_CreateGPUTexture(g->device, &info);
    if (t) {
        SDL_GPUTextureTransferInfo src;
        SDL_zero(src);
        src.transfer_buffer = tb;
        src.pixels_per_row = (Uint32)(rgba->pitch / 4);
        src.rows_per_layer = (Uint32)rgba->h;
        SDL_GPUTextureRegion dst;
        SDL_zero(dst);
        dst.texture = t;
        dst.w = (Uint32)rgba->w;
        dst.h = (Uint32)rgba->h;
        dst.d = 1;
        SDL_UploadToGPUTexture(u->pass, &src, &dst, false);
        if (levels > 1) {
            if (u->mipmapped_count == u->mipmapped_cap) {
                int cap = u->mipmapped_cap ? u->mipmapped_cap * 2 : 64;
                SDL_GPUTexture **m = SDL_realloc(u->mipmapped, (size_t)cap * sizeof *m);
                if (m) { u->mipmapped = m; u->mipmapped_cap = cap; }
            }
            if (u->mipmapped_count < u->mipmapped_cap) u->mipmapped[u->mipmapped_count++] = t;
        }
    }
    if (tb) SDL_ReleaseGPUTransferBuffer(g->device, tb);
    if (rgba != s) SDL_DestroySurface(rgba);
    return t;
}

SDL_GPUTexture *gpu_upload_png(gpu *g, gpu_upload *u, const char *path, bool mipmaps, int *w, int *h) {
    SDL_Surface *s = SDL_LoadPNG(path);
    if (!s) return NULL;
    if (w) *w = s->w;
    if (h) *h = s->h;
    SDL_GPUTexture *t = gpu_upload_surface(g, u, s, mipmaps);
    SDL_DestroySurface(s);
    return t;
}

SDL_GPUBuffer *gpu_upload_buffer(gpu *g, gpu_upload *u, SDL_GPUBufferUsageFlags usage, const void *data, Uint32 size) {
    if (size == 0) return NULL;
    SDL_GPUBufferCreateInfo info;
    SDL_zero(info);
    info.usage = usage;
    info.size = size;
    SDL_GPUTransferBuffer *tb = stage(g, data, size);
    if (!tb) return NULL;
    SDL_GPUBuffer *b = SDL_CreateGPUBuffer(g->device, &info);
    if (b) {
        SDL_GPUTransferBufferLocation src = {tb, 0};
        SDL_GPUBufferRegion dst = {b, 0, size};
        SDL_UploadToGPUBuffer(u->pass, &src, &dst, false);
    }
    SDL_ReleaseGPUTransferBuffer(g->device, tb);
    return b;
}

bool gpu_upload_end(gpu *g, gpu_upload *u) {
    (void)g;
    bool ok = true;
    if (u->pass) SDL_EndGPUCopyPass(u->pass);
    for (int i = 0; i < u->mipmapped_count; i++) SDL_GenerateMipmapsForGPUTexture(u->cmd, u->mipmapped[i]);
    if (u->cmd) ok = SDL_SubmitGPUCommandBuffer(u->cmd);
    SDL_free(u->mipmapped);
    SDL_zerop(u);
    return ok;
}

SDL_GPUTexture *gpu_text(gpu *g, const char *text, int scale, int *w, int *h) {
    int lines = 1, longest = 0, len = 0;
    for (const char *c = text; *c; c++) {
        if (*c == '\n') { lines++; len = 0; continue; }
        if ((*c & 0xC0) != 0x80) longest = SDL_max(longest, ++len);  /* UTF-8: count code points */
    }
    const int glyph = SDL_DEBUG_TEXT_FONT_CHARACTER_SIZE, line = glyph + 2;
    int tw = SDL_max(1, longest * glyph * scale), th = lines * line * scale;
    SDL_Surface *s = SDL_CreateSurface(tw, th, SDL_PIXELFORMAT_RGBA32);
    if (!s) return NULL;
    SDL_GPUTexture *t = NULL;
    SDL_Renderer *r = SDL_CreateSoftwareRenderer(s);
    if (r) {
        SDL_SetRenderDrawColor(r, 255, 255, 255, 0);
        SDL_RenderClear(r);
        SDL_SetRenderScale(r, (float)scale, (float)scale);
        SDL_SetRenderDrawColor(r, 255, 255, 255, 255);
        char *copy = SDL_strdup(text);
        int y = 0;
        /* Line by line (SDL_strtok_r would skip empty lines). */
        for (char *p = copy; p; y++) {
            char *nl = SDL_strchr(p, '\n');
            if (nl) *nl = 0;
            if (*p) SDL_RenderDebugText(r, 0, (float)(y * line), p);
            p = nl ? nl + 1 : NULL;
        }
        SDL_free(copy);
        SDL_RenderPresent(r);
        SDL_DestroyRenderer(r);
        gpu_upload u;
        if (gpu_upload_begin(g, &u)) {
            t = gpu_upload_surface(g, &u, s, false);
            if (!gpu_upload_end(g, &u) && t) { SDL_ReleaseGPUTexture(g->device, t); t = NULL; }
        }
    }
    SDL_DestroySurface(s);
    if (w) *w = tw;
    if (h) *h = th;
    return t;
}

/* ---- frames ---- */

bool gpu_frame_begin(gpu *g, gpu_frame *f) {
    SDL_zerop(f);
    f->cmd = SDL_AcquireGPUCommandBuffer(g->device);
    if (!f->cmd) return false;
    if (!SDL_WaitAndAcquireGPUSwapchainTexture(f->cmd, g->window, &f->target, &f->width, &f->height) || !f->target) {
        SDL_SubmitGPUCommandBuffer(f->cmd);
        f->cmd = NULL;
        return false;
    }
    return true;
}

/* Depth, and with MSAA the multisampled colour target, at the swapchain's size and g->msaa samples. */
static bool ensure_targets(gpu *g, Uint32 w, Uint32 h) {
    if (g->depth && g->target_w == w && g->target_h == h && g->target_samples == g->msaa) return true;
    if (g->depth) SDL_ReleaseGPUTexture(g->device, g->depth);
    if (g->msaa_color) SDL_ReleaseGPUTexture(g->device, g->msaa_color);
    g->depth = g->msaa_color = NULL;
    SDL_GPUTextureCreateInfo info;
    SDL_zero(info);
    info.type = SDL_GPU_TEXTURETYPE_2D;
    info.format = g->depth_format;
    info.usage = SDL_GPU_TEXTUREUSAGE_DEPTH_STENCIL_TARGET;
    info.width = w;
    info.height = h;
    info.layer_count_or_depth = 1;
    info.num_levels = 1;
    info.sample_count = sample_count(g->msaa);
    g->depth = SDL_CreateGPUTexture(g->device, &info);
    if (g->msaa > 1) {
        info.format = g->swapchain_format;
        info.usage = SDL_GPU_TEXTUREUSAGE_COLOR_TARGET;
        g->msaa_color = SDL_CreateGPUTexture(g->device, &info);
    }
    g->target_w = w;
    g->target_h = h;
    g->target_samples = g->msaa;
    if (g->depth && (g->msaa == 1 || g->msaa_color)) return true;
    SDL_Log("GPU: 3D targets: %s", SDL_GetError());
    return false;
}

SDL_GPURenderPass *gpu_pass_3d(gpu *g, gpu_frame *f, SDL_FColor clear) {
    if (!ensure_targets(g, f->width, f->height)) return NULL;
    SDL_GPUColorTargetInfo color;
    SDL_zero(color);
    color.clear_color = clear;
    color.load_op = SDL_GPU_LOADOP_CLEAR;
    if (g->msaa > 1) {  /* draw multisampled, resolve into the swapchain (overlays then draw on that) */
        color.texture = g->msaa_color;
        color.store_op = SDL_GPU_STOREOP_RESOLVE;
        color.resolve_texture = f->target;
        color.cycle = true;
    } else {
        color.texture = f->target;
        color.store_op = SDL_GPU_STOREOP_STORE;
    }
    SDL_GPUDepthStencilTargetInfo depth;
    SDL_zero(depth);
    depth.texture = g->depth;
    depth.clear_depth = 1;
    depth.load_op = SDL_GPU_LOADOP_CLEAR;
    depth.store_op = SDL_GPU_STOREOP_DONT_CARE;
    depth.stencil_load_op = SDL_GPU_LOADOP_DONT_CARE;
    depth.stencil_store_op = SDL_GPU_STOREOP_DONT_CARE;
    depth.cycle = true;
    return SDL_BeginGPURenderPass(f->cmd, &color, 1, &depth);
}

SDL_GPURenderPass *gpu_pass_2d(gpu *g, gpu_frame *f, bool clear, SDL_FColor clear_color) {
    (void)g;
    SDL_GPUColorTargetInfo color;
    SDL_zero(color);
    color.texture = f->target;
    color.clear_color = clear_color;
    color.load_op = clear ? SDL_GPU_LOADOP_CLEAR : SDL_GPU_LOADOP_LOAD;
    color.store_op = SDL_GPU_STOREOP_STORE;
    return SDL_BeginGPURenderPass(f->cmd, &color, 1, NULL);
}

void gpu_frame_end(gpu *g, gpu_frame *f) {
    (void)g;
    if (f->cmd) SDL_SubmitGPUCommandBuffer(f->cmd);
    SDL_zerop(f);
}

/* Must match the Quad block in shaders/ui.vert (std140: four vec4). */
typedef struct ui_quad { float rect[4], uv[4], color[4], target[4]; } ui_quad;
_Static_assert(sizeof(ui_quad) == 64, "ui_quad must match shaders/ui.vert");

void gpu_quad(gpu *g, gpu_frame *f, SDL_GPURenderPass *pass, SDL_GPUTexture *tex, SDL_FRect rect, const SDL_FRect *uv,
              SDL_FColor color) {
    gpu_quad_sampled(g, f, pass, tex, g->ui_sampler, rect, uv, color);
}

void gpu_quad_sampled(gpu *g, gpu_frame *f, SDL_GPURenderPass *pass, SDL_GPUTexture *tex, SDL_GPUSampler *sampler,
                      SDL_FRect rect, const SDL_FRect *uv, SDL_FColor color) {
    ui_quad q = {{rect.x, rect.y, rect.w, rect.h},
                 {uv ? uv->x : 0, uv ? uv->y : 0, uv ? uv->w : 1, uv ? uv->h : 1},
                 {color.r, color.g, color.b, color.a},
                 {(float)f->width, (float)f->height, 0, 0}};
    SDL_GPUTextureSamplerBinding binding = {tex ? tex : g->white, sampler};
    SDL_BindGPUGraphicsPipeline(pass, g->ui);
    SDL_BindGPUFragmentSamplers(pass, 0, &binding, 1);
    SDL_PushGPUVertexUniformData(f->cmd, 0, &q, sizeof q);
    SDL_DrawGPUPrimitives(pass, 6, 1, 0, 0);
}

/* Must match the Quad block in shaders/overlay.vert and the Params block in shaders/overlay.frag (std140). */
typedef struct overlay_quad { float corner[4][4]; } overlay_quad;
typedef struct overlay_params { Uint32 mode; float threshold, pad[2]; } overlay_params;
_Static_assert(sizeof(overlay_quad) == 64, "overlay_quad must match shaders/overlay.vert");

void gpu_overlay(gpu *g, gpu_frame *f, SDL_GPURenderPass *pass, SDL_GPUTexture *tex, const float corners[4][2],
                 const float uv[4][2], int mode, float threshold) {
    static const float full[4][2] = {{0, 0}, {1, 0}, {0, 1}, {1, 1}};
    overlay_quad q;
    for (int i = 0; i < 4; i++) {
        q.corner[i][0] = corners ? corners[i][0] : full[i][0];
        q.corner[i][1] = corners ? corners[i][1] : full[i][1];
        q.corner[i][2] = uv ? uv[i][0] : full[i][0];
        q.corner[i][3] = uv ? uv[i][1] : full[i][1];
    }
    overlay_params p = {(Uint32)mode, threshold, {0, 0}};
    SDL_GPUTextureSamplerBinding binding = {tex ? tex : g->white, g->ui_sampler};
    SDL_BindGPUGraphicsPipeline(pass, g->overlay);
    SDL_BindGPUFragmentSamplers(pass, 0, &binding, 1);
    SDL_PushGPUVertexUniformData(f->cmd, 0, &q, sizeof q);
    SDL_PushGPUFragmentUniformData(f->cmd, 0, &p, sizeof p);
    SDL_DrawGPUPrimitives(pass, 6, 1, 0, 0);
}
